import{_ as r,o as a,c as e,ai as d}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"AI 选型概览","description":"","frontmatter":{},"headers":[],"relativePath":"ai/explore/ai-selection/index.md","filePath":"ai/explore/ai-selection/index.md"}'),l={name:"ai/explore/ai-selection/index.md"};function o(n,t,i,s,h,g){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="ai-选型概览" tabindex="-1">AI 选型概览 <a class="header-anchor" href="#ai-选型概览" aria-label="Permalink to “AI 选型概览”">​</a></h1><blockquote><p><strong>定位</strong>：在 AI 技术快速迭代的 2026 年，如何从纷繁的模型、工具、协议中选出最适合自己场景的方案？本模块提供「选型框架 + 当下推荐 + 避坑指南」，帮助你做决策而非追热点。</p></blockquote><hr><h2 id="为什么需要选型" tabindex="-1">为什么需要选型？ <a class="header-anchor" href="#为什么需要选型" aria-label="Permalink to “为什么需要选型？”">​</a></h2><p>AI 生态已经过了「随便选一个都能用」的阶段。2026 年：</p><ul><li><strong>大模型</strong>：从 GPT、Claude、Qwen、DeepSeek 到 Llama，各有擅长领域</li><li><strong>开发工具</strong>：Cursor、Copilot、Continue、 Windsurf 等 AI 编辑器林立</li><li><strong>协议与 Skill</strong>：MCP、Function Calling、Agent Skill 等标准化方案日趋成熟</li></ul><p><strong>不做选型的后果</strong>：</p><ul><li>用错模型 → 成本高、效果差</li><li>用错工具 → 团队效率不升反降</li><li>用错协议 → 集成困难、维护成本飙升</li></ul><hr><h2 id="选型框架-3-步决策法" tabindex="-1">选型框架：3 步决策法 <a class="header-anchor" href="#选型框架-3-步决策法" aria-label="Permalink to “选型框架：3 步决策法”">​</a></h2><h3 id="第一步-明确约束条件" tabindex="-1">第一步：明确约束条件 <a class="header-anchor" href="#第一步-明确约束条件" aria-label="Permalink to “第一步：明确约束条件”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>关键问题</th><th>影响</th></tr></thead><tbody><tr><td><strong>环境</strong></td><td>本地 / 云端 / 混合？</td><td>决定可用的模型范围与部署成本</td></tr><tr><td><strong>任务</strong></td><td>写代码 / 文档 / RAG / Agent？</td><td>决定对模型能力的要求侧重</td></tr><tr><td><strong>预算</strong></td><td>能接受 API 费用还是自建推理？</td><td>决定是走云端还是本地</td></tr><tr><td><strong>隐私</strong></td><td>数据能否出域？</td><td>决定是否必须本地部署</td></tr><tr><td><strong>团队</strong></td><td>团队技术栈是 Java / Python / 全栈？</td><td>决定工具链的选型倾向</td></tr></tbody></table><h3 id="第二步-按场景匹配方案" tabindex="-1">第二步：按场景匹配方案 <a class="header-anchor" href="#第二步-按场景匹配方案" aria-label="Permalink to “第二步：按场景匹配方案”">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐路径</th><th>侧重</th></tr></thead><tbody><tr><td><strong>日常编码提效</strong></td><td>Cursor + GPT-4o / Claude</td><td>代码理解与生成能力</td></tr><tr><td><strong>企业内部 RAG</strong></td><td>Qwen / Llama（本地）+ 向量库</td><td>隐私与检索质量</td></tr><tr><td><strong>Agent 自动化</strong></td><td>Claude / GPT-4o + MCP + Function Calling</td><td>工具调用稳定性</td></tr><tr><td><strong>文档写作</strong></td><td>Claude（长文本）+ 本地小模型（草稿）</td><td>表达一致性与成本</td></tr><tr><td><strong>学习与实验</strong></td><td>Ollama + 本地开源模型</td><td>低成本试错</td></tr></tbody></table><h3 id="第三步-小规模验证后逐步推广" tabindex="-1">第三步：小规模验证后逐步推广 <a class="header-anchor" href="#第三步-小规模验证后逐步推广" aria-label="Permalink to “第三步：小规模验证后逐步推广”">​</a></h3><blockquote><p><strong>不要一上来就全面铺开</strong>。先选一个场景、一个工具，跑通闭环，再横向扩展。</p></blockquote><hr><h2 id="本模块文章一览" tabindex="-1">本模块文章一览 <a class="header-anchor" href="#本模块文章一览" aria-label="Permalink to “本模块文章一览”">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>适合谁</th><th>核心内容</th></tr></thead><tbody><tr><td><a href="./llm-selection.html">AI 大模型选型指南</a></td><td>所有 AI 使用者</td><td>按环境/场景选择最合适的模型</td></tr><tr><td><a href="./dev-tools-selection.html">AI 开发工具选型</a></td><td>开发者</td><td>IDE 插件、CLI 工具、AI 原生编辑器对比</td></tr><tr><td><a href="./mcp-skill-selection.html">MCP 与 Skill 选型</a></td><td>集成开发者</td><td>协议标准、Server 生态、选型策略</td></tr></tbody></table><hr><h2 id="选型原则-反复提醒自己" tabindex="-1">选型原则（反复提醒自己） <a class="header-anchor" href="#选型原则-反复提醒自己" aria-label="Permalink to “选型原则（反复提醒自己）”">​</a></h2><ol><li><strong>够用就好</strong>：不要为了追新而频繁切换工具，稳定优先</li><li><strong>先跑通再优化</strong>：第一版用最成熟的方案，后续再迭代</li><li><strong>关注生态而非参数</strong>：模型参数大小 ≠ 实际效果，生态完善度更重要</li><li><strong>成本可视化</strong>：把 API 费用、推理成本、维护成本纳入选型考量</li></ol><hr><blockquote><p><strong>下一步</strong>：如果你还不确定从哪开始，建议先读 <a href="./llm-selection.html">AI 大模型选型指南</a>，确定模型的基座，再搭配开发工具与协议。</p></blockquote>',24)])])}const m=r(l,[["render",o]]);export{b as __pageData,m as default};
